// P3.6: renders the plugin and mechanic gallery (public/gallery/index.html) from the reuse index. Generated by
// `npm run index-reuse` together with docs/reuse-index.json, so `npm run check` keeps it fresh. The page is static and
// self-contained (inline CSS/JS/data); it ships with the app (dist/gallery/), so preset links open the live game.
export const GALLERY_FILE = 'public/gallery/index.html';
const REPO = 'https://github.com/mojomast/fpsrizz/blob/main/';

const pick = (e) => {
  const base = { id: e.id, type: e.type, name: e.name ?? e.id, scope: e.scope, summary: e.summary ?? '', keywords: e.keywords ?? [] };
  if (e.type === 'plugin') {
    return { ...base, source: e.source, useWhen: e.useWhen, limitations: e.limitations ?? [], docs: e.docs ?? [], examples: e.examples ?? [],
      entryPoints: e.entryPoints ?? [], enable: e.enable ?? [], presets: (e.presets ?? []).map((p) => p.id), reviewed: !!e.reviewed };
  }
  if (e.type === 'contract') {
    return { ...base, source: e.source, importFrom: e.importFrom, implementations: e.implementations ?? [], documentedBy: e.documentedBy ?? [] };
  }
  return { ...base, useWhen: e.useWhen, plugins: e.plugins ?? [], steps: e.steps ?? [], docs: e.docs ?? [] };
};

const escapeScript = (s) => s.replace(/</g, '\\u003c');

/** @param {{ sourceDigest: string, entries: any[], presets: { id: string, name: string, plugins: string[] }[] }} index */
export function renderGallery(index) {
  const data = {
    digest: index.sourceDigest,
    repo: REPO,
    entries: index.entries.map(pick),
    presets: index.presets.map((p) => ({ id: p.id, name: p.name, plugins: p.plugins })),
  };
  const counts = { plugin: 0, contract: 0, recipe: 0 };
  for (const e of data.entries) counts[e.type] = (counts[e.type] ?? 0) + 1;
  return `<!doctype html>
<!-- Generated by npm run index-reuse (scripts/gallery-lib.mjs). Do not edit. Source digest ${index.sourceDigest} -->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Bulkhead plugin &amp; mechanic gallery</title>
<style>
:root{color-scheme:dark;--bg:#0f1216;--panel:#171c22;--line:#2a323c;--ink:#e6e9ee;--dim:#97a1ad;--acc:#f2b632;--blue:#6fb3ff;--green:#7fd18b}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 system-ui,-apple-system,Segoe UI,Roboto,sans-serif}
header{position:sticky;top:0;z-index:2;background:rgba(15,18,22,.96);border-bottom:1px solid var(--line);padding:14px 20px}
h1{margin:0 0 4px;font-size:20px}h1 span{color:var(--acc)}header p{margin:0;color:var(--dim)}
.bar{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px;align-items:center}
input[type=search]{flex:1 1 280px;min-width:200px;background:var(--panel);border:1px solid var(--line);color:var(--ink);border-radius:6px;padding:8px 10px;font:inherit}
.chip{background:var(--panel);border:1px solid var(--line);color:var(--ink);border-radius:999px;padding:5px 11px;cursor:pointer;font:inherit}
.chip[aria-pressed=true]{background:var(--acc);border-color:var(--acc);color:#111}
main{padding:16px 20px;display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:12px}
.card{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:12px 14px;display:flex;flex-direction:column;gap:6px;min-width:0}
.card h2{margin:0;font-size:15px;overflow-wrap:anywhere}.id{font:12px ui-monospace,Menlo,monospace;color:var(--dim);overflow-wrap:anywhere}
.tag{display:inline-block;font-size:11px;border:1px solid var(--line);border-radius:4px;padding:0 6px;margin-right:4px;color:var(--dim)}
.tag.plugin{color:var(--green);border-color:#2f5a37}.tag.contract{color:var(--blue);border-color:#2b4866}.tag.recipe{color:var(--acc);border-color:#6b5320}
.sum{margin:0}.use{margin:0;color:var(--dim);font-size:13px}.kw{font-size:12px;color:var(--dim)}
.links{display:flex;flex-wrap:wrap;gap:6px;margin-top:auto;padding-top:4px}
.links a{font-size:12px;color:var(--blue);text-decoration:none;border:1px solid var(--line);border-radius:4px;padding:2px 7px}
.links a.play{color:#111;background:var(--acc);border-color:var(--acc);font-weight:600}
details{font-size:12px;color:var(--dim)}details ul{margin:4px 0 0;padding-left:18px}
.empty{grid-column:1/-1;color:var(--dim);text-align:center;padding:40px}
footer{color:var(--dim);font-size:12px;padding:0 20px 20px}
</style>
</head>
<body>
<header>
  <h1><span>Bulkhead</span> plugin &amp; mechanic gallery</h1>
  <p>${counts.plugin} plugins, ${counts.contract} SDK contracts, ${counts.recipe} composition recipes, ${data.presets.length} playable presets. Search by intent ("stamina cooldown", "navmesh", "inventory"); <b>Play</b> opens a preset that uses the plugin.</p>
  <div class="bar">
    <input id="q" type="search" placeholder="Search names, summaries, keywords…" aria-label="Search" autofocus>
    <button class="chip" data-type="all" aria-pressed="true">All</button>
    <button class="chip" data-type="plugin" aria-pressed="false">Plugins</button>
    <button class="chip" data-type="recipe" aria-pressed="false">Recipes</button>
    <button class="chip" data-type="contract" aria-pressed="false">Contracts</button>
    <button class="chip" id="cross" aria-pressed="false" title="Only cross-genre (reviewed reusable) entries">Cross-genre</button>
    <button class="chip" id="playable" aria-pressed="false" title="Only plugins used by a built-in preset">Playable</button>
  </div>
</header>
<main id="grid" aria-live="polite"></main>
<footer>Generated from <a href="${REPO}docs/reuse-index.json" style="color:var(--blue)">docs/reuse-index.json</a> by <code>npm run index-reuse</code> · digest <code>${index.sourceDigest.slice(0, 12)}</code> · agents: use <code>npm run find-reuse</code> for the same data.</footer>
<script id="data" type="application/json">${escapeScript(JSON.stringify(data))}</script>
<script>
(() => {
  const D = JSON.parse(document.getElementById('data').textContent);
  const presetName = new Map(D.presets.map((p) => [p.id, p.name]));
  const grid = document.getElementById('grid'), q = document.getElementById('q');
  const params = new URLSearchParams(location.search);
  const state = { type: params.get('type') || 'all', cross: params.has('cross'), playable: params.has('playable'), q: params.get('q') || '' };
  q.value = state.q;
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
  const repo = (p) => D.repo + String(p).replace(/:\\d+$/, '');
  const hay = (e) => [e.id, e.name, e.summary, e.useWhen, ...(e.keywords || []), ...(e.entryPoints || [])].join(' ').toLowerCase();
  const index = D.entries.map((e) => ({ e, h: hay(e) }));
  const order = { plugin: 0, recipe: 1, contract: 2 };
  function card(e) {
    const links = [];
    for (const id of (e.presets || []).slice(0, 4)) links.push('<a class="play" href="../?preset=' + encodeURIComponent(id) + '" title="' + esc(presetName.get(id) || id) + '">▶ ' + esc(presetName.get(id) || id) + '</a>');
    if (e.source) links.push('<a href="' + esc(repo(e.source)) + '">source</a>');
    for (const d of (e.docs || []).slice(0, 2)) links.push('<a href="' + esc(repo(d)) + '">' + esc(d.split('/').pop()) + '</a>');
    const more = [];
    if (e.entryPoints && e.entryPoints.length) more.push('<li>Entry points: ' + e.entryPoints.map(esc).join(', ') + '</li>');
    if (e.enable && e.enable.length) more.push('<li>Enable: ' + e.enable.map(esc).join(', ') + '</li>');
    if (e.importFrom) more.push('<li>Import from: ' + esc(e.importFrom) + '</li>');
    if (e.implementations && e.implementations.length) more.push('<li>Implemented by: ' + e.implementations.map(esc).join(', ') + '</li>');
    if (e.plugins && e.plugins.length) more.push('<li>Plugins: ' + e.plugins.map(esc).join(', ') + '</li>');
    for (const l of e.limitations || []) more.push('<li>Limit: ' + esc(l) + '</li>');
    return '<article class="card" data-id="' + esc(e.id) + '"><div><span class="tag ' + e.type + '">' + e.type + '</span><span class="tag">' + esc(e.scope || '') + '</span></div>' +
      '<h2>' + esc(e.name) + '</h2><div class="id">' + esc(e.id) + '</div>' +
      (e.summary ? '<p class="sum">' + esc(e.summary) + '</p>' : '') +
      (e.useWhen && e.type !== 'contract' ? '<p class="use">' + esc(e.useWhen) + '</p>' : '') +
      (e.keywords && e.keywords.length && e.type !== 'contract' ? '<div class="kw">' + e.keywords.slice(0, 10).map(esc).join(' · ') + '</div>' : '') +
      (more.length ? '<details><summary>Details</summary><ul>' + more.join('') + '</ul></details>' : '') +
      '<div class="links">' + links.join('') + '</div></article>';
  }
  function render() {
    const terms = state.q.toLowerCase().split(/\\s+/).filter(Boolean);
    const rows = index.filter(({ e, h }) => (state.type === 'all' || e.type === state.type) && (!state.cross || e.scope === 'cross-genre') &&
      (!state.playable || (e.presets && e.presets.length)) && terms.every((t) => h.includes(t)))
      .sort((a, b) => order[a.e.type] - order[b.e.type] || (b.e.scope === 'cross-genre') - (a.e.scope === 'cross-genre') || a.e.id.localeCompare(b.e.id));
    grid.innerHTML = rows.length ? rows.slice(0, 300).map((r) => card(r.e)).join('') + (rows.length > 300 ? '<p class="empty">Showing 300 of ' + rows.length + '. Search or filter to narrow it down.</p>' : '') : '<p class="empty">Nothing matches. Try fewer words.</p>';
    document.querySelectorAll('[data-type]').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.type === state.type)));
    document.getElementById('cross').setAttribute('aria-pressed', String(state.cross));
    document.getElementById('playable').setAttribute('aria-pressed', String(state.playable));
    const p = new URLSearchParams();
    if (state.q) p.set('q', state.q); if (state.type !== 'all') p.set('type', state.type); if (state.cross) p.set('cross', ''); if (state.playable) p.set('playable', '');
    history.replaceState(null, '', p.toString() ? '?' + p : location.pathname);
  }
  q.addEventListener('input', () => { state.q = q.value; render(); });
  document.querySelectorAll('[data-type]').forEach((b) => b.addEventListener('click', () => { state.type = b.dataset.type; render(); }));
  document.getElementById('cross').addEventListener('click', () => { state.cross = !state.cross; render(); });
  document.getElementById('playable').addEventListener('click', () => { state.playable = !state.playable; render(); });
  render();
})();
</script>
</body>
</html>
`;
}
